import java.math.BigDecimal;
import java.math.RoundingMode;

/**
 * 费用计算工具类（纯 Java，无外部依赖）。
 *
 * 规则来源：docs/费用规则.md，与本次需求一致。
 * - 配送费：itemCount == 0 返回 0；itemCount > 0 且 amount > 200 返回 0；否则返回 12。
 * - 服务费：amount == 0 返回 0；0 < amount <= 100 返回 2；amount > 100 返回 5。
 * - 负金额、负件数、null 非法，抛 IllegalArgumentException。
 * - 金额单位为元，返回值统一保留 2 位小数，不修改输入 BigDecimal。
 */
public final class FeeCalculator {

    /** 配送费金额（元）。 */
    private static final BigDecimal DELIVERY_FEE = new BigDecimal("12.00");

    /** 免配送费的订单金额阈值（元），严格大于该值才免配送费。 */
    private static final BigDecimal FREE_DELIVERY_THRESHOLD = new BigDecimal("200");

    /** 服务费：低档金额（元）。 */
    private static final BigDecimal SERVICE_FEE_LOW = new BigDecimal("2.00");

    /** 服务费：高档金额（元）。 */
    private static final BigDecimal SERVICE_FEE_HIGH = new BigDecimal("5.00");

    /** 服务费分档阈值（元），严格大于该值进入高档。 */
    private static final BigDecimal SERVICE_FEE_THRESHOLD = new BigDecimal("100");

    /** 金额返回值统一保留的小数位数。 */
    private static final int SCALE = 2;

    private FeeCalculator() {
        // 工具类，禁止实例化
    }

    /**
     * 计算配送费。
     *
     * @param amount    订单金额（元），不能为 null 且必须 >= 0
     * @param itemCount 商品件数，不能小于 0
     * @return 配送费（元），保留 2 位小数
     * @throws IllegalArgumentException amount 为 null、amount < 0 或 itemCount < 0
     */
    public static BigDecimal deliveryFee(BigDecimal amount, int itemCount) {
        validateAmount(amount);
        validateItemCount(itemCount);

        // 件数为 0：不产生配送费
        if (itemCount == 0) {
            return scale(DELIVERY_FEE.ZERO);
        }

        // 件数 > 0 且金额严格大于 200：免配送费
        if (amount.compareTo(FREE_DELIVERY_THRESHOLD) > 0) {
            return scale(BigDecimal.ZERO);
        }

        // 其余合法情况（含金额恰好等于 200）：收取配送费
        return scale(DELIVERY_FEE);
    }

    /**
     * 计算服务费。
     *
     * @param amount 订单金额（元），不能为 null 且必须 >= 0
     * @return 服务费（元），保留 2 位小数
     * @throws IllegalArgumentException amount 为 null 或 amount < 0
     */
    public static BigDecimal serviceFee(BigDecimal amount) {
        validateAmount(amount);

        // 金额为 0：不产生服务费
        if (amount.compareTo(BigDecimal.ZERO) == 0) {
            return scale(BigDecimal.ZERO);
        }

        // 金额严格大于 100：高档服务费
        if (amount.compareTo(SERVICE_FEE_THRESHOLD) > 0) {
            return scale(SERVICE_FEE_HIGH);
        }

        // 0 < 金额 <= 100：低档服务费
        return scale(SERVICE_FEE_LOW);
    }

    /**
     * 校验金额：不能为 null，且必须 >= 0。
     */
    private static void validateAmount(BigDecimal amount) {
        if (amount == null) {
            throw new IllegalArgumentException("订单金额不能为 null");
        }
        if (amount.compareTo(BigDecimal.ZERO) < 0) {
            throw new IllegalArgumentException("订单金额不能为负数，实际值：" + amount.toPlainString());
        }
    }

    /**
     * 校验件数：不能小于 0。
     */
    private static void validateItemCount(int itemCount) {
        if (itemCount < 0) {
            throw new IllegalArgumentException("商品件数不能为负数，实际值：" + itemCount);
        }
    }

    /**
     * 统一金额返回精度为 2 位小数，且不修改输入对象。
     */
    private static BigDecimal scale(BigDecimal value) {
        return value.setScale(SCALE, RoundingMode.HALF_UP);
    }
}
