import java.math.BigDecimal;

/**
 * FeeCalculator 的独立测试类（main + 断言，无测试框架依赖）。
 *
 * 覆盖：负数、null、0、100、200 及阈值上下相邻金额；配送费额外覆盖件数 0 与 1；
 * 同时验证返回精度为 2 位小数、输入 BigDecimal 未被修改。
 */
public class FeeCalculatorTest {

    private static int passed = 0;
    private static int failed = 0;

    public static void main(String[] args) {
        // ===== 配送费：件数 0 =====
        assertDelivery("delivery: itemCount=0, amount=0", new BigDecimal("0"), 0, "0.00");
        assertDelivery("delivery: itemCount=0, amount=200", new BigDecimal("200"), 0, "0.00");
        assertDelivery("delivery: itemCount=0, amount=999", new BigDecimal("999"), 0, "0.00");

        // ===== 配送费：件数 1，金额阈值 200 上下相邻 =====
        assertDelivery("delivery: itemCount=1, amount=0", new BigDecimal("0"), 1, "12.00");
        assertDelivery("delivery: itemCount=1, amount=199.99", new BigDecimal("199.99"), 1, "12.00");
        assertDelivery("delivery: itemCount=1, amount=200 (恰好等于阈值)", new BigDecimal("200"), 1, "12.00");
        assertDelivery("delivery: itemCount=1, amount=200.01", new BigDecimal("200.01"), 1, "0.00");
        assertDelivery("delivery: itemCount=1, amount=1000", new BigDecimal("1000"), 1, "0.00");

        // ===== 配送费：件数 > 1 =====
        assertDelivery("delivery: itemCount=5, amount=200", new BigDecimal("200"), 5, "12.00");
        assertDelivery("delivery: itemCount=5, amount=200.01", new BigDecimal("200.01"), 5, "0.00");

        // ===== 服务费：0、100、阈值上下相邻 =====
        assertService("service: amount=0", new BigDecimal("0"), "0.00");
        assertService("service: amount=0.01", new BigDecimal("0.01"), "2.00");
        assertService("service: amount=99.99", new BigDecimal("99.99"), "2.00");
        assertService("service: amount=100 (恰好等于阈值)", new BigDecimal("100"), "2.00");
        assertService("service: amount=100.01", new BigDecimal("100.01"), "5.00");
        assertService("service: amount=200", new BigDecimal("200"), "5.00");
        assertService("service: amount=1000", new BigDecimal("1000"), "5.00");

        // ===== 服务费不使用配送费的 200 阈值 =====
        assertService("service: amount=200 仍为 5.00（不受 200 阈值影响）", new BigDecimal("200"), "5.00");

        // ===== 非法输入：null =====
        assertThrows("delivery: amount=null", () -> FeeCalculator.deliveryFee(null, 1));
        assertThrows("service: amount=null", () -> FeeCalculator.serviceFee(null));

        // ===== 非法输入：负金额 =====
        assertThrows("delivery: amount=-0.01", () -> FeeCalculator.deliveryFee(new BigDecimal("-0.01"), 1));
        assertThrows("delivery: amount=-200", () -> FeeCalculator.deliveryFee(new BigDecimal("-200"), 1));
        assertThrows("service: amount=-0.01", () -> FeeCalculator.serviceFee(new BigDecimal("-0.01")));
        assertThrows("service: amount=-100", () -> FeeCalculator.serviceFee(new BigDecimal("-100")));

        // ===== 非法输入：负件数 =====
        assertThrows("delivery: itemCount=-1", () -> FeeCalculator.deliveryFee(new BigDecimal("100"), -1));
        assertThrows("delivery: itemCount=-5", () -> FeeCalculator.deliveryFee(new BigDecimal("100"), -5));

        // ===== 输入 BigDecimal 未被修改 =====
        BigDecimal amount = new BigDecimal("200.005");
        BigDecimal before = new BigDecimal(amount.toPlainString());
        FeeCalculator.deliveryFee(amount, 1);
        FeeCalculator.serviceFee(amount);
        if (amount.compareTo(before) == 0) {
            pass("input BigDecimal 未被修改");
        } else {
            fail("input BigDecimal 被修改：before=" + before.toPlainString()
                    + ", after=" + amount.toPlainString());
        }

        // ===== 返回精度为 2 位小数 =====
        assertScale("delivery 返回精度", FeeCalculator.deliveryFee(new BigDecimal("200"), 1));
        assertScale("service 返回精度", FeeCalculator.serviceFee(new BigDecimal("100")));

        System.out.println();
        System.out.println("通过：" + passed + "，失败：" + failed);
        if (failed > 0) {
            System.out.println("测试未全部通过");
            System.exit(1);
        }
        System.out.println("全部测试通过");
    }

    // ---------- 断言辅助方法 ----------

    private static void assertDelivery(String name, BigDecimal amount, int itemCount, String expected) {
        try {
            BigDecimal actual = FeeCalculator.deliveryFee(amount, itemCount);
            if (actual.compareTo(new BigDecimal(expected)) == 0) {
                pass(name + " -> " + actual.toPlainString());
            } else {
                fail(name + " 期望 " + expected + "，实际 " + actual.toPlainString());
            }
        } catch (RuntimeException e) {
            fail(name + " 抛出异常：" + e);
        }
    }

    private static void assertService(String name, BigDecimal amount, String expected) {
        try {
            BigDecimal actual = FeeCalculator.serviceFee(amount);
            if (actual.compareTo(new BigDecimal(expected)) == 0) {
                pass(name + " -> " + actual.toPlainString());
            } else {
                fail(name + " 期望 " + expected + "，实际 " + actual.toPlainString());
            }
        } catch (RuntimeException e) {
            fail(name + " 抛出异常：" + e);
        }
    }

    private static void assertThrows(String name, Runnable action) {
        try {
            action.run();
            fail(name + " 期望抛出 IllegalArgumentException，但未抛出");
        } catch (IllegalArgumentException e) {
            pass(name + " 抛出 IllegalArgumentException：" + e.getMessage());
        } catch (RuntimeException e) {
            fail(name + " 期望 IllegalArgumentException，实际抛出 " + e.getClass().getName());
        }
    }

    private static void assertScale(String name, BigDecimal value) {
        if (value.scale() == 2) {
            pass(name + " = " + value.toPlainString() + "（scale=2）");
        } else {
            fail(name + " 期望 scale=2，实际 scale=" + value.scale()
                    + "，值=" + value.toPlainString());
        }
    }

    private static void pass(String message) {
        passed++;
        System.out.println("[PASS] " + message);
    }

    private static void fail(String message) {
        failed++;
        System.out.println("[FAIL] " + message);
    }
}
