     * @param itemCount 件数，不能小于 0
     * @return 配送费，保留 2 位小数
     * @throws IllegalArgumentException 如果金额为 null、金额小于 0 或件数小于 0
     */
    public static BigDecimal deliveryFee(BigDecimal amount, int itemCount) {
        validateAmount(amount);
        validateItemCount(itemCount);

        if (itemCount == 0) {
            return BigDecimal.ZERO.setScale(2, RoundingMode.UNNECESSARY);
        }

        if (amount.compareTo(BigDecimal.valueOf(200)) > 0) {
            return BigDecimal.ZERO.setScale(2, RoundingMode.UNNECESSARY);
        }

        return BigDecimal.valueOf(12).setScale(2, RoundingMode.UNNECESSARY);
    }

    /**
     * 计算服务费。
     *
     * @param amount 订单金额，不能为 null，且必须大于等于 0
     * @return 服务费，保留 2 位小数
     * @throws IllegalArgumentException 如果金额为 null 或金额小于 0
     */
    public static BigDecimal serviceFee(BigDecimal amount) {
        validateAmount(amount);

        if (amount.compareTo(BigDecimal.ZERO) == 0) {
            return BigDecimal.ZERO.setScale(2, RoundingMode.UNNECESSARY);
        }

        if (amount.compareTo(BigDecimal.valueOf(100)) <= 0) {
            return BigDecimal.valueOf(2).setScale(2, RoundingMode.UNNECESSARY);
        }

        return BigDecimal.valueOf(5).setScale(2, RoundingMode.UNNECESSARY);
    }

    private static void validateAmount(BigDecimal amount) {
        if (amount == null) {
            throw new IllegalArgumentException("金额不能为 null");
        }
        if (amount.compareTo(BigDecimal.ZERO) < 0) {
            throw new IllegalArgumentException("金额不能小于 0");
        }
    }

    private static void validateItemCount(int itemCount) {
        if (itemCount < 0) {
            throw new IllegalArgumentException("件数不能小于 0");
        }
    }
